def merge_and_save():
    """Merge L0-L11 + L12-L24 -> L0-L24, save to hidden_states_r1_8b_full/."""
    FULL_DIR.mkdir(parents=True, exist_ok=True)
    existing = {f.stem for f in FULL_DIR.glob("*.pt")}

    early_map = {}
    for pt in sorted(EARLY_DIR.glob("*.pt")):
        d = torch.load(pt, map_location="cpu", weights_only=False)
        early_map[d["trace_id"]] = d

    merged_count = 0
    skipped = 0
    for pt in sorted(ORIG_DIR.glob("*.pt")):
        d = torch.load(pt, map_location="cpu", weights_only=False)
        tid = d["trace_id"]
        if tid in existing:
            skipped += 1
            continue
        if tid not in early_map:
            continue

        early = early_map[tid]
        early_hs = early["hidden_states"]   # [T, 12, 4096]
        orig_hs = d["hidden_states"]         # [T, 13, 4096]
        n = min(early_hs.shape[0], orig_hs.shape[0])

        combined = torch.cat([early_hs[:n], orig_hs[:n]], dim=1)  # [T, 25, 4096]

        save_dict = {
            "hidden_states": combined,
            "trace_id": tid,
            "num_sentences": n,
            "commitment_point": d.get("commitment_point"),
            "step_labels": d.get("step_labels"),
            "layers": list(range(25)),
        }
        torch.save(save_dict, FULL_DIR / f"{tid}.pt")
        merged_count += 1

    print(f"Merged {merged_count} traces (skipped {skipped} existing). Total in dir: {merged_count + skipped}")
    return merged_count + skipped


def load_traces():
    traces = []
    for pt in sorted(FULL_DIR.glob("*.pt")):
        d = torch.load(pt, map_location="cpu", weights_only=False)
        if d.get("step_labels") is None or d.get("commitment_point") is None:
            continue
        cp = d["commitment_point"]
        labels = d["step_labels"]
        if isinstance(labels, torch.Tensor):
            labels = labels.tolist()
        if cp <= 0 or cp >= len(labels) or sum(labels) == 0:
            continue
        n = min(d["hidden_states"].shape[0], len(labels))
        traces.append({
            "trace_id": d["trace_id"],
            "hidden_states": d["hidden_states"][:n],
            "step_labels": labels[:n],
            "commitment_point": cp,
        })
    return traces


def split_traces(traces, seed=SEED):
    rng = np.random.default_rng(seed)
    idx = rng.permutation(len(traces))
    nt = int(len(traces) * 0.6)
    nv = int(len(traces) * 0.2)
    return (
        [traces[i] for i in idx[:nt]],
        [traces[i] for i in idx[nt:nt+nv]],
        [traces[i] for i in idx[nt+nv:]],
    )


def build_hs_features(traces, layer_idx, window):
    Xs, ys = [], []
    for t in traces:
        hs = t["hidden_states"][:, layer_idx, :].float().numpy()
        labels = np.array(t["step_labels"], dtype=np.int32)
        n = min(hs.shape[0], len(labels))
        hs, labels = hs[:n], labels[:n]
        if window <= 1:
            Xs.append(hs)
            ys.append(labels)
        else:
            dim = hs.shape[1]
            for i in range(n):
                start = max(0, i - window + 1)
                w = hs[start:i+1]
                if len(w) < window:
                    pad = np.zeros((window - len(w), dim), dtype=np.float32)
                    w = np.concatenate([pad, w], axis=0)
                Xs.append(w.flatten())
                ys.append(labels[i])
    if window <= 1:
        return np.vstack(Xs), np.concatenate(ys)
    return np.array(Xs, dtype=np.float32), np.array(ys, dtype=np.int32)


